const TR = {"а": "a", "б": "b", "в": "v", "г": "g", "д": "d", "е": "e", "ё": "e", "ж": "zh", "з": "z", "и": "i", "й": "y", "к": "k", "л": "l", "м": "m", "н": "n", "о": "o", "п": "p", "р": "r", "с": "s", "т": "t", "у": "u", "ф": "f", "х": "kh", "ц": "ts", "ч": "ch", "ш": "sh", "щ": "shch", "ъ": "", "ы": "y", "ь": "", "э": "e", "ю": "yu", "я": "ya"};
export function cityEn(name) {
  if (!name) return name;
  if (CITY_EN[name]) return CITY_EN[name];
  return name.replace(/[А-Яа-яЁё]/g, (ch) => {
    const lo = ch.toLowerCase(), t = TR[lo] ?? lo;
    return ch === lo ? t : t.charAt(0).toUpperCase() + t.slice(1);
  });
}
const w = (x) => EN[x] ?? CITY_EN[x] ?? x;

